/// <summary>
/// Service class to send sales order invoice business events as a batch
/// </summary>
class METSendSalesOrderInvoiceBusinessEventService extends SysOperationServiceBase
{
    InfoMessage errorMessage;

}

Method.Source:
    /// <summary>
    /// Process the sales order invoices.
    /// </summary>
    public void process()
    {
        CustInvoiceJour     custInvoiceJour;
        METCustInvoiceJour  metCustInvoiceJour;

        try
        {
            select firstonly RecId, InvoiceId from custInvoiceJour
                join RecId from metCustInvoiceJour
                    where metCustInvoiceJour.CustInvoiceJour == custInvoiceJour.RecId
                && metCustInvoiceJour.IntegrationStatus  == METIntegrationStatus::ReadyToSend;

            if(custInvoiceJour.RecId)
            {
                if(BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METSalesInvoicePostedBusinessEvent)))
                {
                    METSalesInvoicePostedBusinessEvent::newFromDataAreaId(curExt()).send();
                }
                else
                {
                    throw error("@MET:SOInvoiceBusinessEventNotEnabled");
                }
            }
        }
        catch (Exception::Error)
        {
            this.getInfologMessage();
            throw error(errorMessage);
        }
    }

    /// <summary>
    /// Gets the latest infolog error message
    /// </summary>
    private void getInfologMessage()
    {
        SysInfologEnumerator sysInfologEnumerator;
        SysInfologMessageStruct sysInfologMessageStruct;

        sysInfologEnumerator = SysInfologEnumerator::newData(infolog.infologData());
        errorMessage = METConstants::emptyString;

        while (sysInfologEnumerator.moveNext())
        {
            sysInfologMessageStruct = new SysInfologMessageStruct(sysInfologEnumerator.currentMessage());
            errorMessage += strfmt(sysInfologMessageStruct.message());
        }
    }
